const black = '#000';
const darkest = '#333';
const dark = '#565656';
const normal = '#ccc';
const light = '#eee';
const lightest = '#f5f5f5';
const white = '#FFF';
const darker = '#898989';
const slightlyDarker = '#acacac';

export const grayscale = {
  black,
  darkest,
  dark,
  normal,
  light,
  lightest,
  white,
  darker,
  slightlyDarker,
};

export const notices = {
  error: 'red',
  warning: 'orange',
  success: 'green',
  notice: 'blue',
};
